from reports.periods import month_range, quarter_range


def sum_in_range(rows, start, end):
    t = 0
    for r in rows:
        if r["date"] >= start and r["date"] < end:
            t = t + r["amount_cents"]
    return t


def monthly_report(rows, year, month):
    start, end = month_range(year, month)
    total = sum_in_range(rows, start, end)
    cnt = len([r for r in rows if r["date"] >= start and r["date"] < end])
    return {"period": "%04d-%02d" % (year, month), "orders": cnt, "total_cents": total}


def quarterly_report(rows, year, quarter):
    start, end = quarter_range(year, quarter)
    total = sum_in_range(rows, start, end)
    cnt = len([r for r in rows if r["date"] >= start and r["date"] < end])
    return {"period": "%04d-Q%d" % (year, quarter), "orders": cnt, "total_cents": total}

"""Date ranges for the sales reports. Every range is half-open: start <= day < end."""

import datetime


def month_range(year, month):
    """Return (first day of the month, first day of the next month)."""
    start = datetime.date(year, month, 1)
    end = datetime.date(year, month + 1, 1)
    return start, end


def quarter_range(year, quarter):
    """Return (first day of the quarter, first day of the next quarter) for quarter 1-4."""
    start = datetime.date(year, 3 * quarter - 2, 1)
    end = datetime.date(year, 3 * quarter + 1, 1)
    return start, end


def week_range(day):
    """Return (Monday of the ISO week containing day, Monday of the following week)."""
    start = day - datetime.timedelta(days=day.weekday())
    return start, start + datetime.timedelta(days=7)

